def gen_file(lang_code, overrides):
    p = dict(EN_P)
    q = dict(EN_Q)
    if 'p' in overrides: p.update(overrides['p'])
    if 'q' in overrides: q.update(overrides['q'])
    lines = [
        "import type { PageTranslations } from './types'",
        "",
        f"export const {lang_code}: PageTranslations = {{",
        "  purposes: {",
    ]
    for k in P_KEYS:
        v = p.get(k, EN_P.get(k, k)).replace('\\', '\\\\').replace("'", "\\'")
        lines.append(f"    {k}: '{v}',")
    lines.append("  },")
    lines.append("  policies: {")
    for k in Q_KEYS:
        v = q.get(k, EN_Q.get(k, k)).replace('\\', '\\\\').replace("'", "\\'")
        lines.append(f"    {k}: '{v}',")
    lines.append("  },")
    lines.append("}")
    path = os.path.join(DIR, f"{lang_code}.ts")
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')
    print(f"Created {lang_code}.ts")

for code, data in LANGS.items():
    gen_file(code, data)
